/* Story replies: direct message referring to the original story. */
(()=>{'use strict';const cfg=window.PATIYIZ_CONFIG;let client=null,pending=false;
function api(){if(!client){if(!cfg?.supabaseUrl||!cfg?.supabasePublishableKey||!window.supabase?.createClient)throw Error('Bağlantı hazır değil');client=window.supabase.createClient(cfg.supabaseUrl,cfg.supabasePublishableKey)}return client}
function pauseStory(){const overlay=document.getElementById('story-overlay');overlay?.querySelector('.story-big-video')?.pause();overlay?.querySelector('.pati-story-share-media-video')?.pause()}
function setup(){const overlay=document.getElementById('story-overlay');if(!overlay||overlay.querySelector('.buchee-story-reply')||overlay.classList.contains('pati-story-own'))return;const like=overlay.querySelector('.pati-story-like');if(!like)return;const owner=overlay.querySelector('.story-player-head .pati-story-owner-name strong')?.textContent||'Hikâye';const footer=document.createElement('form');footer.className='buchee-story-reply';footer.innerHTML='<input name="reply" type="text" maxlength="1000" autocomplete="off" placeholder="Mesaj gönder…" aria-label="Hikâyeye mesaj gönder"><button type="submit" class="buchee-story-send" aria-label="Yanıtı gönder" hidden>Gönder</button><span class="buchee-story-like-slot"></span>';like.parentNode.replaceChild(footer,like);footer.querySelector('.buchee-story-like-slot').append(like);const input=footer.querySelector('input'),send=footer.querySelector('.buchee-story-send');input.addEventListener('input',()=>send.hidden=!input.value.trim());input.addEventListener('focus',()=>{pauseStory();overlay.classList.add('buchee-story-typing')});input.addEventListener('blur',()=>overlay.classList.remove('buchee-story-typing'));footer.addEventListener('submit',async e=>{e.preventDefault();e.stopPropagation();const body=input.value.trim();if(!body||pending)return;pending=true;send.disabled=true;try{const db=api();const {data:{user},error:authErr}=await db.auth.getUser();if(authErr||!user)throw Error('Giriş yapmalısın');const storyId=like.dataset.id;const {data:story,error:storyErr}=await db.from('patiyiz_stories').select('id,author_id,caption,expires_at').eq('id',storyId).single();if(storyErr||!story)throw Error('Hikâye bulunamadı');if(story.author_id===user.id)throw Error('Kendi hikâyene yanıt veremezsin');if(story.expires_at&&Date.parse(story.expires_at)<Date.now())throw Error('Hikâyenin süresi doldu');const excerpt=(story.caption||'Hikâye').slice(0,100);const message='↪ Hikâyene yanıt verdi · '+excerpt+'\n'+body;const r=await db.from('messages').insert({sender_id:user.id,receiver_id:story.author_id,body:message});if(r.error)throw r.error;input.value='';send.hidden=true;input.blur();const note=document.createElement('div');note.className='buchee-story-reply-success';note.textContent='Hikâyeye yanıt gönderildi';footer.append(note);setTimeout(()=>note.remove(),2200)}catch(err){const note=document.createElement('div');note.className='buchee-story-reply-success';note.textContent=err.message||'Mesaj gönderilemedi';footer.append(note);setTimeout(()=>note.remove(),3000)}finally{pending=false;send.disabled=false}})}
let queued=false;const observer=new MutationObserver(()=>{if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;setup()})});observer.observe(document.body,{childList:true,subtree:true});setup()})();
